{"hypotheses": [
  {
    "name": "Hypothesis 1",
    "mechanism": "Firms with high cash and book leverage tend to perform better under low market volatility conditions as they can service their debts without pressure.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "Cash"},
        {"weight": 0.5, "primitive": "BookLeverage"}
      ], 
      "regime": "VIX_BELOW_TRAILING_MEDIAN", 
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Cash", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Hypothesis 2",
    "mechanism": "Momentum strategy can be more effective when combined with the market volatility; firms with high momentum and high market beta tend to outperform in high market volatility periods.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "Mom12m"},
        {"weight": 0.5, "primitive": "Beta"}
      ], 
      "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Hypothesis 3",
    "mechanism": "Firms with relatively low price and high dividend yield likely to deliver stronger returns in a positive term spread regime due to increased investor's confidence.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "Price"},
        {"weight": 0.5, "primitive": "DivYieldST"}
      ], 
      "regime": "TERM_SPREAD_POSITIVE", 
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.5,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Hypothesis 4",
    "mechanism": "Firms with strong sales growth and high gross profits can perform well in a negative term spread regime due to their robust business models.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "GP"},
        {"weight": 0.5, "primitive": "GrSaleToGrInv"}
      ], 
      "regime": "TERM_SPREAD_NEGATIVE", 
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "GP", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Hypothesis 5",
    "mechanism": "Firms with high market momentum and low bid-ask spread tend to achieve high returns in the up trending market due to increased investor's attention.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "BidAskSpread"}
      ], 
      "regime": "MKT_TRAILING_12M_UP", 
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Hypothesis 6",
    "mechanism": "Firms with high earnings consistency and low price tend to perform well in a down trending market due to their stability and low price attractiveness.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "EarningsConsistency"},
        {"weight": -0.5, "primitive": "Price"}
      ], 
      "regime": "MKT_TRAILING_12M_DOWN", 
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "EarningsConsistency", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Hypothesis 7",
    "mechanism": "Combination of strong analyst consensus and high trading volume can lead to superior returns when VIX is below its trailing median due to increased market confidence.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "ConsRecomm"},
        {"weight": 0.5, "primitive": "ShareVol"}
      ], 
      "regime": "VIX_BELOW_TRAILING_MEDIAN", 
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Hypothesis 8",
    "mechanism": "Low price-to-sales ratio combined with positive medium-term reversal can lead to superior returns when VIX is above its trailing median due to potential underpricing.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "SP"},
        {"weight": 0.5, "primitive": "MRreversal"}
      ], 
      "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "SP", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 24
  }
]}
